<template><view class="lottery"><view class="brand"><text>ZO · 神秘宝箱</text><text class="back" @click="back">返回论坛 ›</text></view><view class="intro"><view class="eyebrow">YOUR DAILY SURPRISE</view><view class="heading">开启今日惊喜</view><view class="subtitle">把好运留给热爱游戏的你</view></view><view v-if="error" class="error">{{error}}<button @click="load">重新加载</button></view><view class="glass"><view class="status" v-if="data.loggedIn"><image :src="data.user?.avatar"/><view>{{data.user?.username}}<view class="muted">今日还可开启 {{data.remaining}} 次</view></view></view><view v-else class="status"><view>登录后领取每日开启机会</view><button @click="login">立即登录</button></view><view class="stage"><view :class="['chest',phase]"><view class="lid"></view><view class="body"><view class="lock">✦</view></view><view class="spark s1">✧</view><view class="spark s2">✦</view></view><view v-if="result" class="reveal"><view class="eyebrow">{{result.won?'恭喜获得':'好运正在路上'}}</view><view class="prize">{{result.prize}}</view><view class="muted">{{result.credit_value?result.credit_value+' '+result.credit_title+' 已自动到账':'明天再来，遇见更多惊喜'}}</view></view></view><button class="draw" :disabled="busy||loading||(data.loggedIn&&(!data.enabled||data.reached))" @click="draw"><view class="shine"></view>{{busy?'宝箱开启中…':!data.loggedIn?'登录开启宝箱':!data.enabled?'活动暂未开始':data.reached?'今日次数已用完':'开启神秘宝箱'}}</button><view class="rule">每天 {{data.max_draws||1}} 次机会 · 积分奖励自动到账</view><view v-if="data.announcement_html" class="notice" @click="announcement=true">查看活动公告 ›</view></view><view class="glass"><view class="section">宝箱中的惊喜</view><view class="prizes"><view v-for="p in data.prizes||[]" :key="p.id">✦ {{p.name}}</view><view v-if="!data.enabled" class="muted">活动暂未开始，请关注论坛公告。</view></view></view><view class="glass"><view class="section">我的开启记录</view><view v-for="h in data.history||[]" :key="h.id" class="history"><text>{{h.prize}}</text><text class="muted">{{date(h.dateline)}}</text></view><view v-if="!data.history?.length" class="muted">{{data.loggedIn?'尚无开启记录':'登录查看你的开启记录'}}</view></view><view class="footer">实物奖励请联系论坛管理员领取。<br/>奖池及每日次数以论坛配置为准。</view><view v-if="announcement" class="overlay"><view class="modal"><view class="section">活动公告</view><scroll-view scroll-y class="announcement"><RichPost :content="data.announcement_html"/></scroll-view><button @click="announcement=false">我知道了</button></view></view><view v-if="showResult" class="overlay"><view class="modal result"><view class="result-icon">{{result?.won?'✦':'♡'}}</view><view class="section">{{result?.won?'恭喜你！':'感谢参与'}}</view><view class="prize">{{result?.prize}}</view><view class="muted">{{result?.credit_value?result.credit_value+' '+result.credit_title+' 已自动到账':'好运会在下一次与你相遇'}}</view><button @click="showResult=false">收下好运</button></view></view></view></template>
<script setup>
import {ref} from 'vue'
import {onShow} from '@dcloudio/uni-app'
import {request,post,requireLogin} from '../../api/index.js'
import RichPost from '../../components/RichPost.vue'
const data=ref({}),loading=ref(false),busy=ref(false),error=ref(''),phase=ref('idle'),result=ref(null),announcement=ref(false),showResult=ref(false);let shown=false,requestId=''
const date=x=>new Date(Number(x)*1000).toLocaleDateString()
function login(){requireLogin()}
function back(){uni.navigateBack({fail:()=>uni.reLaunch({url:'/pages/index/index'})})}
async function load(){if(loading.value)return;loading.value=true;try{data.value=await request('lottery/service.php');error.value='';if(data.value.announcement_html&&!shown){shown=true;announcement.value=true}}catch(e){error.value=e.message}finally{loading.value=false}}
async function draw(){if(busy.value||!requireLogin())return;busy.value=true;phase.value='shaking';error.value='';requestId=requestId||Date.now().toString(36)+Math.random().toString(36).slice(2)+Math.random().toString(36).slice(2);try{const value=await post('lottery/service.php',{action:'draw',request_id:requestId});requestId='';phase.value='opened';await new Promise(resolve=>setTimeout(resolve,650));result.value=value;phase.value='gone';showResult.value=true;await load()}catch(e){phase.value='idle';error.value=e.message;uni.showToast({title:e.message,icon:'none'})}finally{busy.value=false}}
onShow(load)
</script>
<style scoped>.lottery{padding:22px 20px 40px;background:linear-gradient(155deg,#f0eaff,#fff4f9);min-height:100vh;color:#282039}.brand{display:flex;justify-content:space-between;font-size:13px;color:#6c5ce7}.back{color:#8e8e93}.intro{text-align:center;padding:42px 0 22px}.eyebrow{font-size:11px;letter-spacing:2px;color:#8e5ce7}.heading{font-size:32px;font-weight:800;margin:12px 0}.subtitle{font-size:13px;color:#8e8e93}.glass{max-width:480px;margin:18px auto;padding:24px;border-radius:24px;background:#ffffffcc;border:1px solid #fff;box-shadow:0 10px 40px #6c5ce712}.status{display:flex;align-items:center;gap:12px;font-size:15px}.status image{width:40px;height:40px;border-radius:50%}.status button{font-size:12px;margin:0 0 0 auto}.stage{position:relative;height:250px;display:flex;align-items:center;justify-content:center}.chest{width:146px;height:120px;position:relative;filter:drop-shadow(0 20px 25px #6c5ce735)}.lid{height:46px;border-radius:26px 26px 8px 8px;background:linear-gradient(135deg,#9a7cf4,#6c5ce7);border:4px solid #e4c8ff;transform-origin:bottom left}.body{position:relative;height:78px;background:linear-gradient(135deg,#8e5ce7,#51429f);border-radius:7px 7px 18px 18px;border:4px solid #e4c8ff;display:flex;justify-content:center;align-items:center}.lock{background:#ffd787;color:#8e5ce7;border-radius:12px;padding:7px 11px;font-size:24px;margin-top:-32px;border:3px solid #fff0ba}.spark{position:absolute;color:#e6b757;font-size:30px}.s1{top:-40px;left:-30px}.s2{top:6px;right:-34px}.shaking{animation:shake .45s infinite}.opened .lid{transform:rotate(-35deg) translateY(-20px);transition:transform .6s}.gone{opacity:0;transform:scale(.75);transition:.4s}.reveal{position:absolute;text-align:center;animation:reveal .6s ease}.prize{font-size:28px;font-weight:800;color:#8e5ce7;margin:14px 0}.draw{position:relative;overflow:hidden;background:linear-gradient(120deg,#6c5ce7,#a95cdc);border-radius:30px;font-weight:700;border:0}.draw[disabled]{opacity:.5;background:#aaa;color:#fff}.shine{position:absolute;width:30px;height:120px;background:#ffffff40;transform:rotate(25deg);top:-40px;animation:shine 3s infinite}.rule,.notice{text-align:center;font-size:12px;color:#8e8e93;margin-top:16px}.notice{color:#6c5ce7}.section{font-size:19px;font-weight:700;margin-bottom:18px}.prizes{display:flex;flex-wrap:wrap;gap:12px}.prizes view{padding:9px 13px;background:#6c5ce710;color:#6c5ce7;border-radius:14px;font-size:13px}.history{display:flex;justify-content:space-between;padding:12px 0;border-bottom:1px solid #8e8e9320}.footer{text-align:center;color:#8e8e93;font-size:12px;line-height:1.8;margin:25px 0}.overlay{position:fixed;inset:0;z-index:100;display:flex;align-items:center;justify-content:center;background:#1c143b70;padding:24px}.modal{background:var(--card);color:var(--ink);border-radius:24px;padding:28px;width:100%;max-width:420px}.announcement{max-height:45vh}.modal button{margin-top:24px;background:#6c5ce7}.result{text-align:center}.result-icon{font-size:48px;color:#e6b757}.error{max-width:480px;margin:auto}@keyframes shake{0%,100%{transform:rotate(-4deg)}50%{transform:rotate(4deg) translateY(-4px)}}@keyframes reveal{from{opacity:0;transform:translateY(15px)}to{opacity:1;transform:translateY(0)}}@keyframes shine{from{left:-15%}to{left:130%}}@media(prefers-color-scheme:dark){.lottery{background:linear-gradient(155deg,#171225,#24182e);color:#f2f2f7}.glass{background:#30253a88;border-color:#ffffff12}.prizes view{background:#6c5ce730;color:#c8b5ff}}</style>
